const equipmentRecordPage=edit&&!edit.isNew&&<EquipmentRecordPage key={edit.id} asset={edit} staff={staff} canManage={canManage} isAdmin={!!access.user?.isAdmin} editing={recordEditing} saving={saving} dirty={dirty} error={error} message={message} backLabel={recordBackLabel} onBack={closeAsset} onEdit={()=>{setRecordEditing(true);setError('')}} onCancel={cancelRecordEdits} onPrint={()=>{setPrintFormat('qr');setPrinting([edit])}} onDelete={deleteAsset} onReceipt={reference=>setReceiptWindow(reference)} editor={assetEditor} related={<div className="actions assetrecordlinks" aria-label="Related records">{staff.some(s=>s.id===edit.staffId||edit.assignee&&s.email.toLowerCase()===edit.assignee.toLowerCase())&&<ActionHelp label="View Assigned Staff" text="Open the current assignee’s staff record and their assigned equipment. This does not change the assignment."><button type="button" className="secondary" onClick={()=>linkedStaff(staff.find(s=>s.id===edit.staffId||edit.assignee&&s.email.toLowerCase()===edit.assignee.toLowerCase())!.id)}>View Assigned Staff</button></ActionHelp>}{audits.find(a=>a.expected?.some((item:any)=>item.id===edit.id))&&<ActionHelp label="Latest Inventory Check" text="Open the most recent inventory check that included this Asset ID. Review its verification result there."><button type="button" className="secondary" onClick={()=>linkedAudit(audits.find(a=>a.expected?.some((item:any)=>item.id===edit.id)).id)}>Latest Inventory Check</button></ActionHelp>}<ActionHelp label="View Equipment Tickets" text="Show tickets linked to this Asset ID. Opening the list does not create a ticket."><button type="button" className="secondary" onClick={()=>relatedTickets(edit.id)}>View Equipment Tickets</button></ActionHelp></div>} assignment={<><EquipmentAcknowledgement asset={edit}/>{recordControls('assignment')}</>} documents={recordControls('documents')} history={<><EventHistory staff={staff} compact events={events.filter(e=>e.assetId===edit.id)}/>{access.user?.isAdmin&&<RecordRecovery blocked={dirty} asset={edit} refresh={async()=>{await load();const r=await fetch('/api/assets');const d:any=await readApiResponse(r);const a=d.assets?.find((a:any)=>a.id===edit.id);if(a)setEdit({...a,isNew:false})}}/>}</>}/>;
